// Seleção da seção
const secao = String(($json.secao || "")).trim().toLowerCase();
let dados;
if (secao === "tabela") dados = DADOS.TABELA_PRECOS;
else if (secao === "estrategia") dados = DADOS.ESTRATEGIA_VENDA;
else dados = DADOS;

// Retorno
return [
  {
    json: {
      ok: true,
      secao: secao || "tudo",
      consulta: $json.consulta || "",
      dados,
    },
  },
];
